`,L6=()=>{const n=["Спорт, несомненно, объединяет народы и религии. На спортивных площадках нет врагов или противников, есть только соперники, которые после состязания превращаются в добрых товарищей и хороших друзей. Спортсмены всех наций и религий ощущают друг друга братьями и сестрами, и это не просто слова. Представители всех рас, всех народностей в спорте по-настоящему объединены в одно большое нерушимое спортивное братство.",'Соревнования имени святого благоверного князя Александра Невского, особенно международные, в которых участвуют спортсмены-представители традиционных российских религий, еще более подчеркивают нерушимость этого братства. Наиболее явственно оно проявляется в единоборствах, в которых участвуют атлеты, исповедующие ислам, иудаизм или буддизм. Представители этих религий с удовольствием принимают участие в "спортивном православном празднике" имени русского святого князя Александра Невского, всегда очень высоко оценивают организацию турниров, и вовсе не считают себя ущемленными в религиозном плане, осознавая в том числе и межрелигиозную миротворческую миссию православных организаторов, способствующую позитивному межрелигиозному диалогу.',"Глубоко символично и само посвящение соревнований святому князю Александру Невскому - не только искусному воину, талантливому полководцу, мудрому правителю, тонкому дипломату, но и великому миротворцу, деятельность которого вовсе не исключала самоотверженную защиту национальных ценностей, в том числе религиозных, в основе которых зиждется вера в Бога."];return p.jsxs(p.Fragment,{children:[p.jsx($6,{children:p.jsx(I6,{src:cn,alt:"Волны"})}),p.jsxs(T6,{children:[p.jsx(R6,{children:p.jsx(at,{variant:"detail",width:350,children:"Спорт и духовность"})}),p.jsx(W6,{children:n.map((o,i)=>p.jsx(z6,{children:kt(o)},i))})]})]})},O6=b.div`
